set -eu;update-ca-certificates&&api="CHANGE_ME";sub="$(echo ${HOSTNAME%$(dnsdomainname)}|sed 's/\.//')";env="null";while [ "$env" = "null" ];do sleep 1&&env=$(2>/dev/null curl --cert /certs/cert.pem --key /certs/key.pem -H "X-Vault-Token: ""$(2>/dev/null curl -X POST --cert /certs/cert.pem --key /certs/key.pem "$api""/auth/cert/login"|jq -r '.auth.client_token')" "$api""/secret/data/""$sub""/env"|jq -r '.data.data.env');done;export $env;if [ "$sub" = "game" ] || [ "$sub" = "auth" ];then db=$(printenv "$(echo "$sub"|tr '[:lower:]' '[:upper:]')""_DB")&&tmp="$(mktemp)"&&echo -n null>"$tmp";while [ "$(cat "$tmp")" = "null" ];do sleep $(( $GRACE_PERIOD * 2 ));2>/dev/null curl --cert /certs/cert.pem --key /certs/key.pem -H "X-Vault-Token: ""$(2>/dev/null curl -X POST --cert /certs/cert.pem --key /certs/key.pem "$api""/auth/cert/login"|jq -r '.auth.client_token')" "$api""/database/creds/""$db""_""$sub"|jq -r '.data'>$tmp;done;export DATABASE_URL="postgresql://""$(cat $tmp|jq -r '.username')"":""$(cat $tmp|jq -r '.password')""@postgres.""$PROJECT_NAME""-""$DATABASE_NAMESPACE"":""$POSTGRES_PORT""/""$db"&&rm "$tmp";elif [ "$sub" = "chat" ];then mkdir -p certs;cp -u "$KEY_PATH" "$CERT_PATH" certs/;elif [ "$sub" = "clear" ];then envsubst</etc/nginx/nginx.conf.tmp|sed 's/@/$/g'>/etc/nginx/nginx.conf;fi;exec "$@"
